// Background options. Textures are static alpha-mask tiles in
// src/assets/textures/ (generated by scripts/make-textures.mjs), filled with a
// palette role at `alpha` when drawn — so they suit every palette.
// `scale` multiplies the size unit u, so patterns keep their proportion on
// every output size.
export const TEXTURES = [
  // `tile` is the tile's pixel size (used to draw the picker swatches at scale).
  { id: 'paper', label: 'Paper', role: 'text', alpha: 0.16, scale: 1, tile: 256 },
  { id: 'linen', label: 'Linen', role: 'text', alpha: 0.13, scale: 1, tile: 256 },
  { id: 'grain', label: 'Grain', role: 'text', alpha: 0.12, scale: 1, tile: 192 },
  { id: 'dots', label: 'Dots', role: 'mutedText', alpha: 0.3, scale: 1, tile: 40 },
  { id: 'grid', label: 'Grid', role: 'divider', alpha: 0.95, scale: 1, tile: 48 },
  { id: 'lines', label: 'Stripes', role: 'divider', alpha: 0.85, scale: 1, tile: 22 },
];

export const getTexture = (id) => TEXTURES.find((t) => t.id === id) ?? null;

export const BACKGROUNDS = [
  { id: 'paper', label: 'Solid', needs: null },
  // 'texture' keeps its original id (paper grain) so saved drafts stay valid.
  { id: 'texture', label: 'Paper', needs: null, texture: 'paper' },
  { id: 'tex-linen', label: 'Linen', needs: null, texture: 'linen' },
  { id: 'tex-grain', label: 'Grain', needs: null, texture: 'grain' },
  { id: 'tex-dots', label: 'Dots', needs: null, texture: 'dots' },
  { id: 'tex-grid', label: 'Grid', needs: null, texture: 'grid' },
  { id: 'tex-lines', label: 'Stripes', needs: null, texture: 'lines' },
  { id: 'gradient', label: 'Gradient', needs: null },
  { id: 'photo', label: 'Photo', needs: 'backgroundImage' },
  { id: 'source', label: 'Source image', needs: 'contentImage' },
];

export const getBackground = (id) => BACKGROUNDS.find((b) => b.id === id) ?? BACKGROUNDS[0];

export const DEFAULT_BACKGROUND_ID = 'paper';
